-- -----------------------------------------------------------------------
-- Page access
--
-- Participants arrive from a letter and are not logged in, so every study
-- page needs read access for all groups. Without these rows the pages render
-- "Kein Zugriff — Um diese Seite zu erreichen müssen Sie eingeloggt sein."
--
-- Write permissions go to admin only. The surveyJS / labJS styles store
-- responses through UserInput, not through page ACL, so participants do not
-- need insert rights here.
-- -----------------------------------------------------------------------

INSERT IGNORE INTO `acl_groups` (`id_groups`, `id_pages`, `acl_select`, `acl_insert`, `acl_update`, `acl_delete`)
    SELECT g.id, p.id, 1,
           IF(g.name = 'admin', 1, 0), IF(g.name = 'admin', 1, 0), IF(g.name = 'admin', 1, 0)
    FROM `groups` g
    CROSS JOIN `pages` p
    WHERE p.keyword IN ('kanji-adults', 'kanji-adults-survey',
                        'kanji-adults-task', 'kanji-adults-questions');

-- Guest access. Participants arrive from a letter without logging in, and the
-- guest user (id 1) belongs to no group — core checks ACL against the session
-- user, so group grants alone never apply to it. Public pages therefore need a
-- direct `acl_users` row, which is how the existing open pages (home, login,
-- theorie, …) are configured.
INSERT IGNORE INTO `acl_users` (`id_users`, `id_pages`, `acl_select`, `acl_insert`, `acl_update`, `acl_delete`)
    SELECT (SELECT id FROM users WHERE email = 'guest'), p.id, 1, 0, 0, 0
    FROM `pages` p
    WHERE p.keyword IN ('kanji-adults', 'kanji-adults-survey',
                        'kanji-adults-task', 'kanji-adults-questions');


-- -----------------------------------------------------------------------
-- Study content: SurveyJS surveys
-- `config` is the working copy and `published` the live one; both are set
-- so the surveys go live immediately. view_surveys derives survey_name
-- from config.title.default.
-- -----------------------------------------------------------------------

SET @part1_json = '{"title":{"default":"Kanji Lernaufgabe","en":"Kanji Learning Task","fr":"Exercice d\'apprentissage Kanji","it":"Compito di apprendimento Kanji"},"locale":"de","showQuestionNumbers":"off","showProgressBar":"top","progressBarType":"pages","pages":[{"name":"consent","elements":[{"type":"html","name":"A1","html":{"default":"<p><strong>Liebe Eltern/ Liebe Erziehungsberechtigte</strong></p>\\n<p>Wir freuen uns, Ihnen im Rahmen unserer aktuellen Forschung eine Lernaufgabe vorlegen zu dürfen. Ihr Kind hat in der Schule bereits eine ähnliche Aufgabe lösen dürfen.</p>\\n<p>Das Lösen der Aufgabe und die Beantwortung der Fragen ist freiwillig und dauert etwa 30 Minuten.</p>\\n<p>Ihre Antworten sind pseudonymisiert, das bedeutet, Ihnen wird ein persönlicher Code zugewiesen. Dadurch wissen wir nicht, welche Daten zu welcher Familie gehören. Die erhobenen Daten werden nur für die Forschung genutzt und nicht an andere weitergegeben.</p>\\n<p>Ihre Teilnahme ist von grosser Bedeutung von uns!</p>\\n<p>Vielen Dank<br>Herzliche Grüsse,</p>\\n<p>Das Team der Abteilung Entwicklungspsychologie der Universität Bern</p>","en":"<p><strong>Dear Parents/Guardians</strong></p>\\n<p>We are pleased to present you with a learning task as part of our current research. Your child has already completed similar tasks at school.</p>\\n<p>Completing the task and answering the questions is voluntary and takes about 30 minutes.<br>Your answers are pseudonymized, which means that you will be assigned a personal code. This means that we do not know which data belongs to which family. The data collected will only be used for research purposes and will not be passed on to others.</p>\\n<p>Your participation is very important to us – Thank you very much!</p>\\n<p>Kind regards,</p>\\n<p>The Developmental Psychology Department team at the University of Bern</p>","fr":"<p><strong>Chers parents / Chers titulaires de l’autorité parentale</strong></p>\\n<p>Nous sommes heureux de pouvoir vous présenter, dans le cadre de notre recherche actuelle, une tâche d’apprentissage. Votre enfant a déjà effectué des tâches similaires à l’école.</p>\\n<p>La réalisation de l’activité et la réponse aux questions sont facultatives et prennent environ 30 minutes.<br>Vos réponses sont pseudonymisées, ce qui signifie qu’un code personnel vous sera attribué. Ainsi, nous ne savons pas quelles données appartiennent à quelle famille. Les données recueillies seront utilisées uniquement à des fins de recherche et ne seront pas transmises à des tiers.</p>\\n<p>Votre participation est très importante- Merci beaucoup!</p>\\n<p>Avec nos salutations les meilleures,</p>\\n<p>L’équipe du Département de psychologie du développement de l’Université de Berne</p>","it":"<p><strong>Cari genitori / cari tutori legali,</strong></p>\\n<p>Siamo lieti di potervi presentare un compito di apprendimento nell’ambito della nostra attuale ricerca.</p>\\n<p>Lo svolgimento dell’attività e la risposta alle domande sono volontari e richiedono circa 30 minuti.</p>\\n<p>Le Sue risposte sono pseudonimizzate, ciò significa che Le verrà assegnato un codice personale. In questo modo, non sappiamo quali dati appartengano a quale famiglia. I dati raccolti saranno utilizzati esclusivamente per la ricerca e non saranno trasmessi ad altri.</p>\\n<p>La vostra partecipazione è di grande importanza per noi – grazie di cuore!</p>\\n<p>Cordiali saluti,<br>Il team del dipartimento di psicologia dello sviluppo dell’università di Berna</p>"}},{"type":"radiogroup","name":"EV","title":{"default":"Sind Sie mit der Teilnahme an der Aufgabe einverstanden?","en":"Do you consent to participating in the learning task?","fr":"Acceptez-vous de participer à l\'exercice d\'apprentissage?","it":"Acconsente alla partecipazione al compito di apprendimento?"},"isRequired":true,"choices":[{"value":"1","text":{"default":"Ja","en":"Yes","fr":"Oui","it":"Si"}},{"value":"2","text":{"default":"Nein","en":"No","fr":"Non","it":"No"}}]}]},{"name":"consent_declined","visibleIf":"{EV} = \'2\'","elements":[{"type":"html","name":"declined_msg","html":{"default":"<p>Vielen Dank. Ohne Ihr Einverständnis können wir die Aufgabe nicht durchführen. Sie können das Fenster nun schliessen.</p>","en":"<p>Thank you. Without your consent we cannot proceed with the task. You may now close this window.</p>","fr":"<p>Merci. Sans votre consentement, nous ne pouvons pas poursuivre. Vous pouvez fermer cette fenêtre.</p>","it":"<p>Grazie. Senza il suo consenso non possiamo procedere. Può chiudere questa finestra.</p>"}}]},{"name":"code","visibleIf":"{EV} = \'1\'","elements":[{"type":"text","name":"ID_1","title":{"default":"Um Ihre Antworten anonym Ihrem Kind zuordnen zu können, haben Sie einen Code auf dem Brief erhalten. Bitte geben Sie diesen Code jetzt in das Textfeld ein:","en":"In order to assign your answers anonymously to your child, you have received a code on the letter. Please enter this code in the text field now:","fr":"  Pour pouvoir attribuer vos réponses de façon anonyme à votre enfant, vous avez reçu un code dans la lettre. Veuillez entrer ce code maintenant dans le champ de texte:","it":"Per poter attribuire le vostre risposte in modo anonimo a vostro figlio, avete ricevuto un codice sulla lettera. Inserite ora questo codice nel campo di testo:"},"isRequired":true,"validators":[{"type":"text","minLength":3,"text":{"default":"Bitte geben Sie den Code vom Brief ein.","en":"Please enter the code from the letter.","fr":"Veuillez saisir le code figurant sur la lettre.","it":"Inserisca il codice riportato nella lettera."}}]},{"type":"html","name":"A2","html":{"default":"<p>Machen Sie die Aufgabe an einem <strong>ruhigen</strong> Ort.</p>\\n<p>So werden Sie nicht gestört.</p>","en":"<p>Complete the task in a <strong>quiet</strong> place.</p>\\n<p>That way, you won\'t be disturbed.</p>","fr":"<p>Faites la tâche dans un endroit <strong>calme</strong>.<br>Ainsi, vous ne serez pas dérangé(e).</p>","it":"<p>Svolga il compito in un 