SET @study_json = '{"components":{"c1":{"title":"Learn stimulus","type":"lab.html.Screen","content":"<div class=\\"kanji-stage kanji-pair\\"><img class=\\"kanji-item\\" src=\\"${ this.files[this.parameters.kanji_img] }\\"><img class=\\"kanji-item\\" src=\\"${ this.files[this.parameters.meaning_img] }\\"></div>","timeout":"5000","files":[{"localPath":"Fixationskreuz.jpg","poolPath":"{{ASSET_BASE}}/Fixationskreuz.jpg"},{"localPath":"Herbst_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Herbst_Kanji.jpg"},{"localPath":"Herbst.jpg","poolPath":"{{ASSET_BASE}}/Herbst.jpg"},{"localPath":"Ast_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Ast_Kanji.jpg"},{"localPath":"Ast.jpg","poolPath":"{{ASSET_BASE}}/Ast.jpg"},{"localPath":"Baumwolle_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Baumwolle_Kanji.jpg"},{"localPath":"Baumwolle.jpg","poolPath":"{{ASSET_BASE}}/Baumwolle.jpg"},{"localPath":"Pflanze_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Pflanze_Kanji.jpg"},{"localPath":"Pflanze.jpg","poolPath":"{{ASSET_BASE}}/Pflanze.jpg"},{"localPath":"Welt_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Welt_Kanji.jpg"},{"localPath":"Welt.jpg","poolPath":"{{ASSET_BASE}}/Welt.jpg"},{"localPath":"Stock_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Stock_Kanji.jpg"},{"localPath":"Stock.jpg","poolPath":"{{ASSET_BASE}}/Stock.jpg"},{"localPath":"Zeit_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Zeit_Kanji.jpg"},{"localPath":"Zeit.jpg","poolPath":"{{ASSET_BASE}}/Zeit.jpg"},{"localPath":"Dunkelheit_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Dunkelheit_Kanji.jpg"},{"localPath":"Dunkelheit.jpg","poolPath":"{{ASSET_BASE}}/Dunkelheit.jpg"},{"localPath":"Nebel_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Nebel_Kanji.jpg"},{"localPath":"Nebel.jpg","poolPath":"{{ASSET_BASE}}/Nebel.jpg"},{"localPath":"Wald_Kanji.jpg","poolPath":"{{ASSET_BASE}}/Wald_Kanji.jpg"},{"localPath":"Wald.jpg","poolPath":"{{ASSET_BASE}}/Wald.jpg"},{"localPath":"See_Kanji.jpg","poolPath":"{{ASSET_BASE}}/See_Kanji.jpg"},{"localPath":"See.jpg","poolPath":"{{ASSET_BASE}}/See.jpg"},{"localPath":"Klipp