-- Task styling.
SET @task_css = '/* Kanji Adults — lab.js task styling.\n   Paste into the study\'s global CSS (lab.js Builder → Study → Style),\n   or ship via the labJS style\'s `css` field. */\n\n.kanji-stage {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  min-height: 70vh;\n  gap: 2rem;\n}\n\n/* Fixation cross — small and centred. */\n.kanji-fix { width: 64px; height: auto; }\n\n/* Learning trial: kanji and meaning side by side.\n   Matches the Qualtrics LA2 layout (max-width 45% each). */\n.kanji-pair {\n  flex-direction: row;\n  flex-wrap: wrap;\n  gap: 20px;\n}\n.kanji-pair .kanji-item {\n  max-width: 45%;\n  height: auto;\n  object-fit: contain;\n}\n\n/* Recall trial: kanji cue above, options below. */\n.kanji-cue {\n  max-width: 35%;\n  height: auto;\n  object-fit: contain;\n}\n\n.kanji-choices {\n  display: flex;\n  justify-content: center;\n  gap: 20px;\n  flex-wrap: wrap;\n}\n\n.kanji-opt {\n  border: 2px solid #000;\n  border-radius: 12px;\n  background: #fff;\n  padding: 6px;\n  cursor: pointer;\n  transition: border-color .2s ease, transform .1s ease;\n}\n.kanji-opt img {\n  width: 200px;\n  height: auto;\n  border-radius: 10px;\n  display: block;\n}\n.kanji-opt:hover { border-color: #2563eb; }\n.kanji-opt:active { transform: scale(.98); }\n\n/* Confidence scale — three smaller tiles. */\n.kanji-cj .kanji-opt img { width: 120px; }\n\n.kanji-wait { color: #999; font-size: 2rem; }\n\n/* Touch targets on small screens. */\n@media (max-width: 768px) {\n  .kanji-opt img { width: 40vw; }\n  .kanji-cj .kanji-opt img { width: 24vw; }\n  .kanji-cue { max-width: 60%; }\n  .kanji-pair .kanji-item { max-width: 44%; }\n}\n';
INSERT INTO `sections_fields_translation` (`id_sections`, `id_fields`, `id_languages`, `id_genders`, `content`)
VALUES (@sec_task, get_field_id('css'), '0000000001', '0000000001', @task_css)
ON DUPLICATE KEY UPDATE `content` = VALUES(`content`);
